(function(){const still=window.matchMedia("(prefers-reduced-motion: reduce)");function start(hero){const slides=Array.from(hero.querySelectorAll(".bb-hero__slides > figure"));const dotsBar=hero.querySelector(".bb-hero__dots");if(slides.length<2||!dotsBar){return;}
const dots=Array.from(dotsBar.querySelectorAll("button"));const interval=parseInt(hero.dataset.interval,10)||7000;let current=0;let wanted=0;let request=0;let timer=0;let visible=true;async function show(index){wanted=(index+slides.length)%slides.length;const next=wanted;const turn=++request;window.clearTimeout(timer);const image=slides[next].querySelector("img");if(image?.dataset.bbHeroSrc){if(image.dataset.bbHeroSrcset){image.srcset=image.dataset.bbHeroSrcset;}
image.src=image.dataset.bbHeroSrc;delete image.dataset.bbHeroSrc;delete image.dataset.bbHeroSrcset;}
if(image&&(!image.complete||image.naturalWidth===0)){try{await image.decode();}catch{if(turn===request){wanted=current;schedule();}
return;}}
if(turn!==request){return;}
current=next;hero.classList.add("has-turned");slides.forEach((slide,i)=>slide.classList.toggle("is-current",i===current));dots.forEach((dot,i)=>dot.setAttribute("aria-pressed",i===current?"true":"false"));schedule();}
function schedule(){window.clearTimeout(timer);if(visible&&!still.matches&&!document.hidden){timer=window.setTimeout(()=>show(current+1),interval);}}
dots.forEach((dot,i)=>dot.addEventListener("click",()=>show(i)));window.bluebirdSwipe(hero.querySelector(".bb-hero__slides"),(step)=>show(wanted+step));const card=hero.querySelector(".bb-hero__card");if(card){const clear=()=>hero.style.setProperty("--bb-hero-card",card.offsetHeight+"px");clear();new ResizeObserver(clear).observe(card);}
hero.querySelectorAll(".bb-turn").forEach((turn)=>{turn.addEventListener("click",()=>show(wanted+(turn.classList.contains("bb-turn--back")?-1:1)),);turn.hidden=false;});window.bluebirdSwipe.keys(dotsBar,(step)=>{show(wanted+step);dots[wanted].focus();});dotsBar.hidden=false;new IntersectionObserver((entries)=>{visible=entries[0].isIntersecting;schedule();}).observe(hero);document.addEventListener("visibilitychange",schedule);still.addEventListener("change",schedule);schedule();}
document.querySelectorAll(".bb-hero").forEach(start);})();